"use client";

import { useMemo, useState } from "react";
import {
  BarChart,
  Bar,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  ReferenceLine,
  Cell,
} from "recharts";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { formatCurrency } from "@/lib/data";
import type { PaperState } from "@/lib/types";

interface HourlyPnlChartProps {
  paperState: PaperState;
}

interface HourlyBucket {
  hour: string;
  grossPnl: number;
  fees: number;
  net: number;
  cumulative: number;
  tradeCount: number;
}

type ViewMode = "cumulative" | "hourly";

function computeHourlyPnl(paperState: PaperState): HourlyBucket[] {
  const ec = paperState.equity_curve || [];
  const trades = paperState.trade_log || [];
  if (ec.length < 2) return [];

  const initialEquity = paperState.initial_equity ?? 100000;

  // Group equity_curve points by UTC hour — use the LAST point in each hour
  // as that hour's closing equity. The delta between consecutive hours is
  // the true P&L for that hour (matches Coinbase settlement).
  const hourlyEquity = new Map<string, number>();
  for (const p of ec) {
    const d = new Date(p.ts);
    const key = `${String(d.getUTCMonth() + 1).padStart(2, "0")}/${String(d.getUTCDate()).padStart(2, "0")} ${String(d.getUTCHours()).padStart(2, "0")}:00`;
    hourlyEquity.set(key, p.equity);
  }

  // Count trades per hour (for display only)
  const tradesByHour = new Map<string, number>();
  const feesByHour = new Map<string, number>();
  for (const t of trades) {
    const d = new Date(t.ts);
    const key = `${String(d.getUTCMonth() + 1).padStart(2, "0")}/${String(d.getUTCDate()).padStart(2, "0")} ${String(d.getUTCHours()).padStart(2, "0")}:00`;
    tradesByHour.set(key, (tradesByHour.get(key) || 0) + 1);
    feesByHour.set(key, (feesByHour.get(key) || 0) + (t.fee || 0));
  }

  const sortedHours = Array.from(hourlyEquity.entries()).sort(([a], [b]) => a.localeCompare(b));

  let prevEquity = initialEquity;
  return sortedHours.map(([hour, equity]) => {
    const net = equity - prevEquity;
    const fees = feesByHour.get(hour) || 0;
    const gross = net + fees;
    const cumulative = equity - initialEquity;
    prevEquity = equity;
    return {
      hour,
      grossPnl: Math.round(gross * 100) / 100,
      fees: Math.round(fees * 100) / 100,
      net: Math.round(net * 100) / 100,
      cumulative: Math.round(cumulative * 100) / 100,
      tradeCount: tradesByHour.get(hour) || 0,
    };
  });
}

function StatBox({ label, value, color }: { label: string; value: string; color: string }) {
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-[10px] text-muted-foreground uppercase tracking-wide">{label}</span>
      <span className={`text-sm font-mono font-bold ${color}`}>{value}</span>
    </div>
  );
}

export function HourlyPnlChart({ paperState }: HourlyPnlChartProps) {
  const [view, setView] = useState<ViewMode>("cumulative");
  const data = useMemo(() => computeHourlyPnl(paperState), [paperState]);

  if (data.length === 0) return null;

  // Use equity_curve for ground-truth totals (matches Coinbase settlement).
  // Per-hour breakdown from trade_log is directional context only.
  const ec = paperState.equity_curve || [];
  const initialEquity = paperState.initial_equity ?? 100000;
  const currentEquity = ec.length > 0 ? ec[ec.length - 1].equity : initialEquity;
  const totalNet = currentEquity - initialEquity;
  const totalFees = data.reduce((s, d) => s + d.fees, 0);
  const totalGross = totalNet + totalFees;
  const bestHour = data.reduce((best, d) => (d.net > best.net ? d : best), data[0]);
  const worstHour = data.reduce((worst, d) => (d.net < worst.net ? d : worst), data[0]);
  const winHours = data.filter((d) => d.net > 0).length;
  const lossHours = data.filter((d) => d.net < 0).length;

  return (
    <Card>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-mono">
            Hourly P&L
            <span className="text-muted-foreground font-normal ml-2">
              ({data.length} hours)
            </span>
          </CardTitle>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setView("cumulative")}
              className={`px-2.5 py-1 text-xs font-mono rounded-md transition-colors ${
                view === "cumulative"
                  ? "bg-emerald-500/20 text-emerald-400 border border-emerald-500/30"
                  : "text-muted-foreground hover:text-foreground border border-transparent"
              }`}
            >
              Cumulative
            </button>
            <button
              onClick={() => setView("hourly")}
              className={`px-2.5 py-1 text-xs font-mono rounded-md transition-colors ${
                view === "hourly"
                  ? "bg-emerald-500/20 text-emerald-400 border border-emerald-500/30"
                  : "text-muted-foreground hover:text-foreground border border-transparent"
              }`}
            >
              Per Hour
            </button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Stats row */}
        <div className="grid grid-cols-3 sm:grid-cols-6 gap-3 p-3 rounded-lg bg-muted/50">
          <StatBox
            label="Net P&L"
            value={`${totalNet >= 0 ? "+" : ""}${formatCurrency(totalNet)}`}
            color={totalNet >= 0 ? "text-emerald-400" : "text-red-400"}
          />
          <StatBox
            label="Gross P&L"
            value={formatCurrency(totalGross)}
            color="text-foreground"
          />
          <StatBox
            label="Total Fees"
            value={`-${formatCurrency(totalFees)}`}
            color="text-red-400"
          />
          <StatBox
            label="Best Hour"
            value={`+${formatCurrency(bestHour.net)}`}
            color="text-emerald-400"
          />
          <StatBox
            label="Worst Hour"
            value={formatCurrency(worstHour.net)}
            color="text-red-400"
          />
          <StatBox
            label="Win/Loss Hrs"
            value={`${winHours}/${lossHours}`}
            color="text-foreground"
          />
        </div>

        {/* Chart */}
        {view === "cumulative" ? (
          <ResponsiveContainer width="100%" height={300}>
            <AreaChart data={data}>
              <defs>
                <linearGradient id="cumPnlGradient" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#34d399" stopOpacity={0.3} />
                  <stop offset="95%" stopColor="#34d399" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
              <XAxis
                dataKey="hour"
                tick={{ fontSize: 10, fill: "#71717a" }}
                interval="preserveStartEnd"
                tickFormatter={(v) => {
                  const parts = v.split(" ");
                  return parts.length === 2 ? parts[0] : v;
                }}
              />
              <YAxis
                tick={{ fontSize: 10, fill: "#71717a" }}
                tickFormatter={(v) => `$${v}`}
              />
              <Tooltip
                content={({ active, payload }) => {
                  if (!active || !payload || payload.length === 0) return null;
                  const d = payload[0].payload as HourlyBucket;
                  return (
                    <div className="bg-zinc-900 border border-white/10 rounded-lg px-3 py-2 text-xs font-mono">
                      <p className="text-zinc-400 mb-1">{d.hour} UTC</p>
                      <p className="text-zinc-100 font-semibold">
                        Cumulative: {formatCurrency(d.cumulative)}
                      </p>
                      <p className={d.net >= 0 ? "text-emerald-400" : "text-red-400"}>
                        This hour: {d.net >= 0 ? "+" : ""}{formatCurrency(d.net)}
                      </p>
                      <p className="text-zinc-500">{d.tradeCount} trades</p>
                    </div>
                  );
                }}
              />
              <ReferenceLine y={0} stroke="#71717a" strokeDasharray="4 2" />
              <Area
                type="monotone"
                dataKey="cumulative"
                stroke="#34d399"
                strokeWidth={2}
                fill="url(#cumPnlGradient)"
                dot={false}
                activeDot={{ r: 4, fill: "#34d399" }}
              />
            </AreaChart>
          </ResponsiveContainer>
        ) : (
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={data}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
              <XAxis
                dataKey="hour"
                tick={{ fontSize: 10, fill: "#71717a" }}
                interval="preserveStartEnd"
                tickFormatter={(v) => {
                  const parts = v.split(" ");
                  return parts.length === 2 ? parts[0] : v;
                }}
              />
              <YAxis
                tick={{ fontSize: 10, fill: "#71717a" }}
                tickFormatter={(v) => `$${v}`}
              />
              <Tooltip
                content={({ active, payload }) => {
                  if (!active || !payload || payload.length === 0) return null;
                  const d = payload[0].payload as HourlyBucket;
                  return (
                    <div className="bg-zinc-900 border border-white/10 rounded-lg px-3 py-2 text-xs font-mono">
                      <p className="text-zinc-400 mb-1">{d.hour} UTC</p>
                      <p className={`font-semibold ${d.net >= 0 ? "text-emerald-400" : "text-red-400"}`}>
                        Net: {d.net >= 0 ? "+" : ""}{formatCurrency(d.net)}
                      </p>
                      <p className="text-zinc-300">Gross: {formatCurrency(d.grossPnl)}</p>
                      <p className="text-zinc-500">Fees: -{formatCurrency(d.fees)}</p>
                      <p className="text-zinc-500">{d.tradeCount} trades</p>
                    </div>
                  );
                }}
              />
              <ReferenceLine y={0} stroke="#71717a" strokeDasharray="4 2" />
              <Bar dataKey="net" radius={[2, 2, 0, 0]}>
                {data.map((entry, idx) => (
                  <Cell
                    key={idx}
                    fill={entry.net >= 0 ? "rgba(52, 211, 153, 0.7)" : "rgba(248, 113, 113, 0.7)"}
                    stroke={entry.net >= 0 ? "#34d399" : "#f87171"}
                    strokeWidth={1}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        )}
      </CardContent>
    </Card>
  );
}

